    <link rel="stylesheet" href="" xintegrity="sha512DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="noreferrer">
    <style>
        @charset "utf8";
        @import url('');
        :root {
            primary: 39FF14; secondary: 0A61F7; accent: 0A61F7;
            borderglow: rgba(57, 255, 20, 0.5); primaryrgb: 57, 255, 20;
            bg: 000000; surface: rgba(10, 10, 10, 0.6); glass: rgba(255, 255, 255, 0.03);
            glassstrong: rgba(255, 255, 255, 0.06); border: rgba(255, 255, 255, 0.1);
            text: f1f5f9; textmuted: 94a3b8; radiuslg: 20px; radiusmd: 14px;
            radiussm: 10px; shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
            transitioncurve: cubicbezier(0.25, 0.8, 0.25, 1); transitioncolor: 20s easeinout;
        }
         { margin: 0; padding: 0; boxsizing: borderbox; webkittaphighlightcolor: transparent; }
        html { height: 100%; height: webkitfillavailable; scrollbehavior: smooth; touchaction: manipulation; }
        body {
            fontfamily: 'Inter', sansserif; background: var(bg); color: var(text);
            minheight: 100vh; minheight: webkitfillavailable; overflow: hidden;
            webkitfontsmoothing: antialiased; fontsize: 15px; overscrollbehavior: none;
        }
        .aurorabackground { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointerevents: none; zindex: 1; }
        .aurora { position: absolute; borderradius: 50%; mixblendmode: screen; filter: blur(140px); opacity: 0; transition: backgroundcolor 20s easeinout, opacity 12s easeinout; animation: pulse 45s easeinout infinite alternate; }
        .aurora.visible { opacity: 0.25; }
        .aurora.one { width: 80vmax; height: 80vmax; animationname: moveone, pulse; animationduration: 240s, 50s; animationtimingfunction: easeinout, easeinout; animationiterationcount: infinite, infinite; animationdirection: alternate, alternate; }
        .aurora.two { width: 70vmax; height: 70vmax; animationname: movetwo, pulse; animationduration: 210s, 55s; animationtimingfunction: easeinout, easeinout; animationiterationcount: infinite, infinite; animationdirection: alternate, alternate; }
        @keyframes moveone { from { transform: translate(20vw, 20vh) scale(1); } to { transform: translate(50vw, 80vh) scale(1.2); } }
        @keyframes movetwo { from { transform: translate(80vw, 30vh) scale(1); } to { transform: translate(10vw, 60vh) scale(1.3); } }
        @keyframes pulse { from { opacity: 0.2; } to { opacity: 0.4; } }
        .container { display: flex; flexdirection: column; minheight: 100vh; minheight: webkitfillavailable; overflow: hidden; }
        .header { padding: 8px 12px; height: 48px; background: var(surface); backdropfilter: blur(40px) saturate(180%); borderbottom: 1px solid var(border); display: flex; alignitems: center; justifycontent: spacebetween; position: sticky; top: 0; zindex: 100; }
        .headertitle { fontsize: 1rem; fontweight: 600; background: lineargradient(135deg, var(primary), var(secondary)); webkitbackgroundclip: text; webkittextfillcolor: transparent; textshadow: 0 0 20px var(borderglow); position: absolute; left: 50%; transform: translateX(50%); }
        .headerbtn { width: 36px; height: 36px; borderradius: 50%; border: none; background: transparent; color: var(textmuted); fontsize: 1rem; cursor: pointer; transition: all 0.2s; display: flex; alignitems: center; justifycontent: center; }
        .headerbtn:hover { background: var(glassstrong); color: var(text); }
        .chatarea { flex: 1; display: flex; flexdirection: column; overflow: hidden; }
        .messagescontainer { padding: 12px; overflowy: auto; flex: 1; maxheight: calc(100vh  96px); }
        .welcomescreen { textalign: center; maxwidth: 500px; margin: 0 auto; padding: 30px 20px; display: flex; flexdirection: column; alignitems: center; justifycontent: center; height: 100%; animation: fadeIn 1s var(transitioncurve); }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        .welcometitle { fontsize: 2.2rem; fontweight: 800; background: lineargradient(135deg, var(primary), var(secondary)); webkitbackgroundclip: text; webkittextfillcolor: transparent; marginbottom: 0.5rem; }
        .welcomesubtitle { fontsize: 0.9rem; lineheight: 1.5; marginbottom: 1.2rem; color: var(textmuted); }
        .startbtn { padding: 10px 20px; fontsize: 0.9rem; minheight: 42px; background: var(glassstrong); border: 1px solid var(border); borderradius: var(radiusmd); color: var(text); fontweight: 600; cursor: pointer; transition: all 0.2s var(transitioncurve); display: inlineflex; alignitems: center; gap: 8px; }
        .startbtn:hover { bordercolor: var(borderglow); transform: translateY(2px) scale(1.03); }
        .message { marginbottom: 20px; animation: messageSlideIn 0.4s var(transitioncurve); userselect: none; webkituserselect: none; }
        @keyframes messageSlideIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        .usermessage { display: flex; justifycontent: flexend; }
        .userbubble { color: fff; padding: 10px 14px; borderradius: var(radiuslg) var(radiuslg) var(radiussm) var(radiuslg); maxwidth: 80%; fontweight: 500; fontsize: 0.9rem; lineheight: 1.4; boxshadow: 0 2px 8px rgba(0, 0, 0, 0.3); background: lineargradient(135deg, var(primary), var(secondary)); cursor: pointer; }
        .aimessage { display: flex; flexdirection: column; maxwidth: 90%; }
        .aibubble { background: var(glass); border: 1px solid var(border); borderradius: var(radiuslg) var(radiuslg) var(radiuslg) var(radiussm); padding: 10px 14px; lineheight: 1.5; fontsize: 0.9rem; whitespace: prewrap; wordwrap: breakword; cursor: pointer; }
        .inputarea { padding: 8px 12px; background: rgba(5, 2, 10, 0.6); backdropfilter: blur(30px) saturate(150%); bordertop: 1px solid var(border); position: sticky; bottom: 0; zindex: 50; flexshrink: 0; }
        @supports (padding: max(0px)) { .inputarea { paddingbottom: max(8px, env(safeareainsetbottom)); } }
        .inputwrapper { display: flex; gap: 8px; alignitems: flexend; }
        .messageinput { flex: 1; background: var(glassstrong); border: 1px solid var(border); borderradius: 20px; padding: 10px 14px; color: var(text); fontsize: 0.9rem; resize: none; outline: none; transition: all 0.2s var(transitioncurve); minheight: 40px; maxheight: 140px; fontfamily: inherit; lineheight: 1.4; }
        .messageinput:focus { bordercolor: var(primary); boxshadow: 0 0 15px 2px var(primary); }
        .sendbtncontainer { width: 40px; height: 40px; flexshrink: 0; }
        .sendbtn { width: 100%; height: 100%; borderradius: 50%; cursor: pointer; display: flex; alignitems: center; justifycontent: center; border: none; background: var(primary); color: white; transition: all 0.2s var(transitioncurve); fontsize: 0.9rem; }
        .sendbtn:disabled { background: var(glassstrong); color: var(textmuted); cursor: notallowed; }
        .sendbtn:not(:disabled):hover { transform: scale(1.08); boxshadow: 0 0 15px var(primary); }
        .aibubble pre { backgroundcolor: rgba(0,0,0,0.3); borderradius: var(radiussm); padding: 10px; margin: 10px 0; fontfamily: 'Courier New', Courier, monospace; fontsize: 0.85em; whitespace: prewrap; wordwrap: breakword; position: relative; }
        .aibubble code { fontfamily: 'Courier New', Courier, monospace; backgroundcolor: rgba(255,255,255,0.1); padding: 2px 5px; borderradius: 4px; }
        .aibubble pre > code { backgroundcolor: transparent; padding: 0; }
        .copycodebtn { position: absolute; top: 6px; right: 6px; background: var(glassstrong); border: 1px solid var(border); color: var(textmuted); padding: 3px 7px; borderradius: 5px; cursor: pointer; fontsize: 0.75em; transition: all 0.2s; opacity: 0.5; }
        .aibubble pre:hover .copycodebtn { opacity: 1; }
        .copycodebtn:hover { background: var(primary); color: white; bordercolor: var(primary); }

        /  ÚJ: Keresési állapot és források stílusai  /
        .searchstatus { fontsize: 0.8rem; color: var(textmuted); marginbottom: 8px; display: flex; alignitems: center; gap: 8px; animation: fadeIn 0.5s; }
        .searchstatus .faspin { fontsize: 0.7rem; }
        .sourcescontainer { margintop: 12px; bordertop: 1px solid var(border); paddingtop: 8px; }
        .sourcestitle { fontsize: 0.75rem; fontweight: 600; color: var(textmuted); marginbottom: 6px; }
        .sourcelink { display: block; fontsize: 0.8rem; color: var(primary); textdecoration: none; whitespace: nowrap; overflow: hidden; textoverflow: ellipsis; marginbottom: 4px; transition: color 0.2s; }
        .sourcelink:hover { color: var(secondary); }

        /  MÓDOSÍTVA: A másolás gomb stílusai és a PWA viewport  /
        copyOverlay { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; display: flex; alignitems: center; justifycontent: center; backgroundcolor: rgba(0, 0, 0, 0.4); backdropfilter: blur(12px); webkitbackdropfilter: blur(12px); zindex: 200; opacity: 0; pointerevents: none; transition: opacity 0.3s var(transitioncurve); }
        copyOverlay.visible { opacity: 1; pointerevents: all; }
        copyBtn { padding: 16px 32px; fontsize: 1.1rem; fontweight: 600; color: var(text); background: rgba(255, 255, 255, 0.15); border: 1px solid rgba(255, 255, 255, 0.2); borderradius: var(radiusmd); backdropfilter: blur(15px); webkitbackdropfilter: blur(15px); boxshadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4); cursor: pointer; transform: scale(0.9); transition: transform 0.3s var(transitioncurve), backgroundcolor 0.2s; minheight: 48px; minwidth: 120px; }
        copyOverlay.visible copyBtn { transform: scale(1); }
        copyBtn:hover { background: rgba(255, 255, 255, 0.25); }
        copyBtn:active { transform: scale(0.98); }
    </style>
</head>
<body>
    <div class="aurorabackground"> <div class="aurora one"></div> <div class="aurora two"></div> </div>
    <div class="container">
        <header class="header">
            <button class="headerbtn" id="newChatBtn" title="Új beszélgetés"> <i class="fas faplus"></i> </button>
            <h1 class="headertitle">JadedLight</h1>
            <div style="width: 36px;"></div>
        </header>
        <div class="chatarea">
            <section class="messagescontainer" id="messagesContainer" arialive="polite">
                <header class="welcomescreen" id="welcomeScreen">
                    <h1 class="welcometitle">JadedLight</h1>
                    <p class="welcomesubtitle">Autonóm AI asszisztens webkereséssel.</p>
                    <button class="startbtn" onclick="hideWelcome()"> <i class="fas farocket"></i> Kezdjük! </button>
                </header>
            </section>
            <footer class="inputarea">
                <div class="inputwrapper">
                    <textarea class="messageinput" id="messageInput" placeholder="Írj egy üzenetet..." rows="1" arialabel="Üzenet beviteli mező"></textarea>
                    <div class="sendbtncontainer">
                        <button class="sendbtn" id="sendBtn" onclick="sendMessage()" arialabel="Üzenet küldése" disabled> <i class="fas fapaperplane"></i> </button>
                    </div>
                </div>
            </footer>
        </div>
    </div>
    <div id="copyOverlay"> <button id="copyBtn"><i class="far facopy"></i> Másolás</button> </div>

    <script>
        const AppState = { isTyping: false, userId: 'user_' + Math.random().toString(36).substr(2, 9) };
        const API_BASE_URL = '/api';
        const messagesContainer = document.getElementById('messagesContainer');
        const messageInput = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const newChatBtn = document.getElementById('newChatBtn');
        const copyOverlay = document.getElementById('copyOverlay');
        const copyBtn = document.getElementById('copyBtn');
        let welcomeScreen = document.getElementById('welcomeScreen');

        // A DynamicThemeManager és a legtöbb segédfüggvény változatlan...
        class DynamicThemeManager {
            constructor() {
                this.root = document.documentElement;
                this.auroraBlobs = document.querySelectorAll('.aurora');
                this.colorPairs = [
                    {primary: '39FF14', secondary: '0A61F7'}, // Neon zöld és élénk kék  MINDIG ELSŐ!
                    {primary: '0A61F7', secondary: '39FF14'}, // Élénk kék és neon zöld
                    {primary: '39FF14', secondary: '00FFFF'}  // Neon zöld és ciánkék
                ];
                this.currentIndex = 0;
                this.updateColors(this.colorPairs[0]); // Mindig neon zöldkék indítás
                setInterval(() => this.cyclePalette(), 90000); // 90 másodperc váltási idő
                setTimeout(() => this.auroraBlobs.forEach(b => b.classList.add('visible')), 500);
            }

            updateColors(pair) {
                const primaryRGB = this.hexToRgb(pair.primary).join(',');
                this.root.style.setProperty('primary', pair.primary);
                this.root.style.setProperty('secondary', pair.secondary);
                this.root.style.setProperty('borderglow', rgba(${primaryRGB}, 0.5));
                this.auroraBlobs.forEach((blob, i) => {
                    blob.style.backgroundColor = i % 2 === 0 ? pair.primary : pair.secondary;
                });
            }

            hexToRgb(hex) {
                let r = 0, g = 0, b = 0;
                if (hex.length == 7) {
                    r = parseInt(hex.substring(1, 3), 16);
                    g = parseInt(hex.substring(3, 5), 16);
                    b = parseInt(hex.substring(5, 7), 16);
                }
                return [r, g, b];
            }

            cyclePalette = () => {
                this.currentIndex = (this.currentIndex + 1) % this.colorPairs.length;
                this.updateColors(this.colorPairs[this.currentIndex]);
            }
        }

        function hideWelcome() { if (welcomeScreen) { welcomeScreen.style.animation = 'fadeOut 0.5s forwards'; setTimeout(() => { if (welcomeScreen) welcomeScreen.style.display = 'none'; welcomeScreen = null; }, 500); } }
        function newChat() { messagesContainer.innerHTML = ''; const newWelcome = document.createElement('header'); newWelcome.className = 'welcomescreen'; newWelcome.id = 'welcomeScreen'; newWelcome.innerHTML = <h1 class="welcome-title">JadedLight</h1><p class="welcome-subtitle">Autonóm AI asszisztens webkereséssel.</p><button class="start-btn" onclick="hideWelcome()"><i class="fas fa-rocket"></i> Kezdjük!</button>; messagesContainer.appendChild(newWelcome); welcomeScreen = newWelcome; messageInput.value = ''; messageInput.dispatchEvent(new Event('input')); }

        async function sendMessage() {
            const message = messageInput.value.trim();
            if (!message || AppState.isTyping) return;
            hideWelcome();
            addUserMessage(message);
            messageInput.value = '';
            messageInput.dispatchEvent(new Event('input'));
            AppState.isTyping = true;
            sendBtn.disabled = true;

            const aiBubble = createAiMessageContainer();
            messagesContainer.appendChild(aiBubble.container);
            scrollToBottom();

            try {
                const response = await fetch(${API_BASE_URL}/chat, {
                    method: 'POST', headers: { 'ContentType': 'application/json' },
                    body: JSON.stringify({ message, user_id: AppState.userId })
                });
                if (!response.ok) throw new Error(Szerverhiba: ${response.status});
                await streamResponseToBubble(response, aiBubble);
            } catch (error) {
                aiBubble.content.innerHTML += <p style="color: #ff5555;"><strong>Hiba:</strong> ${escapeHtml(error.message)}</p>;
            } finally {
                AppState.isTyping = false;
                sendBtn.disabled = messageInput.value.trim().length === 0;
            }
        }

        //  MÓDOSÍTVA: Stream feldolgozás metaüzenetekkel és folyamatos görgetéssel 
        async function streamResponseToBubble(response, bubbleElements) {
            const { container, content, status } = bubbleElements;
            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            let buffer = '';
            let isRendering = false;
            let autoScrollInterval = null;

            const render = () => {
                if (!isRendering) return;

                // Metaüzenetek feldolgozása
                if (buffer.includes('[SEARCHING_WEB]')) {
                    status.innerHTML = <i class="fas fa-globe fa-spin"></i> Keresés a weben...;
                    container.insertBefore(status, content);
                    buffer = buffer.replace('[SEARCHING_WEB]\n', '');
                }
                if (buffer.includes('[SOURCES:')) {
                    const sourcesMatch = buffer.match(/\[SOURCES:(.?)\]\n/);
                    if (sourcesMatch) {
                        const urls = sourcesMatch[1].split(',');
                        displaySources(container, urls);
                        buffer = buffer.replace(sourcesMatch[0], '');
                    }
                }

                content.innerHTML = simpleMarkdown(buffer);
                requestAnimationFrame(render);
            };

            const startAutoScroll = () => {
                autoScrollInterval = setInterval(() => {
                    const targetScroll = messagesContainer.scrollHeight;
                    const currentScroll = messagesContainer.scrollTop;
                    const containerHeight = messagesContainer.clientHeight;

                    if (currentScroll + containerHeight < targetScroll) {
                        messagesContainer.scrollBy({
                            top: 2,
                            behavior: 'auto'
                        });
                    }
                }, 16); // ~60fps sima görgetés
            };

            const stopAutoScroll = () => {
                if (autoScrollInterval) {
                    clearInterval(autoScrollInterval);
                    autoScrollInterval = null;
                }
                scrollToBottom(); // Végső pozicionálás
            };

            const startRendering = () => { 
                if (!isRendering) { 
                    isRendering = true; 
                    requestAnimationFrame(render);
                    startAutoScroll();
                } 
            };

            const stopRendering = () => {
                isRendering = false;
                stopAutoScroll();
                content.innerHTML = simpleMarkdown(buffer); // Final render
                addCopyButtonsToCode(content);
                addLongPressCopy(content);
                if (status && status.parentNode) {
                    status.remove(); // Keresési állapot eltávolítása a végén
                }
            };

            startRendering();

            while (true) {
                const { value, done } = await reader.read();
                if (done) { stopRendering(); break; }
                buffer += decoder.decode(value, { stream: true });
            }
        }

        //  ÚJ: Források megjelenítése 
        function displaySources(messageContainer, urls) {
            let sourcesDiv = messageContainer.querySelector('.sourcescontainer');
            if (!sourcesDiv) {
                sourcesDiv = document.createElement('div');
                sourcesDiv.className = 'sourcescontainer';
                const title = document.createElement('div');
                title.className = 'sourcestitle';
                title.textContent = 'Források';
                sourcesDiv.appendChild(title);
                messageContainer.appendChild(sourcesDiv);
            }
            sourcesDiv.innerHTML += urls.map(url => 
                <a href="${url}" target="_blank" rel="noopener noreferrer" class="source-link">${new URL(url).hostname}</a>
            ).join('');
        }

        function addUserMessage(message) {
            const messageDiv = document.createElement('div');
            messageDiv.className = 'message usermessage';
            const bubble = document.createElement('div');
            bubble.className = 'userbubble';
            bubble.textContent = message;
            messageDiv.appendChild(bubble);
            messagesContainer.appendChild(messageDiv);
            addLongPressCopy(bubble);
            scrollToBottom();
        }

        function createAiMessageContainer() {
            const container = document.createElement('div');
            container.className = 'message aimessage';
            const status = document.createElement('div');
            status.className = 'searchstatus';
            const content = document.createElement('div');
            content.className = 'aibubble';
            container.appendChild(content);
            return { container, content, status };
        }

        // A többi segédfüggvény (addLongPressCopy, simpleMarkdown, stb.) változatlan...
        function addLongPressCopy(element){let pressTimer=null;const start=(e)=>{if(e.target.closest('pre'))return;pressTimer=setTimeout(()=>{navigator.vibrate?.(50);const textToCopy=element.innerText;copyBtn.dataset.text=textToCopy;copyBtn.innerHTML='<i class="far facopy"></i> Másolás';copyOverlay.classList.add('visible')},500)};const cancel=()=>{clearTimeout(pressTimer)};element.addEventListener("mousedown",start);element.addEventListener("touchstart",start,{passive:true});element.addEventListener("mouseup",cancel);element.addEventListener("mouseleave",cancel);element.addEventListener("touchend",cancel);element.addEventListener("touchcancel",cancel)}
        function simpleMarkdown(text){let html=escapeHtml(text).replace(/\\(.?)\\/g,'<strong>$1</strong>').replace(/\(.?)\/g,'<em>$1</em>').replace(/(\w*)\n([\s\S]*?)/g,(match,lang,code)=><pre><code class="${lang||''}">${code}</code></pre>).replace(/(.*?)/g,'<code>$1</code>');return html}
        function addCopyButtonsToCode(container){container.querySelectorAll('pre').forEach(pre=>{if(pre.querySelector('.copycodebtn'))return;const btn=document.createElement('button');btn.className='copycodebtn';btn.innerHTML='<i class="far facopy"></i>';btn.title='Kód másolása';btn.onclick=(e)=>{e.stopPropagation();const code=pre.querySelector('code').innerText;copyToClipboard(code,btn)};pre.appendChild(btn)})}
        function copyToClipboard(text,btnElement){const textArea=document.createElement('textarea');textArea.value=text;document.body.appendChild(textArea);textArea.select();try{document.execCommand('copy');if(btnElement){btnElement.innerHTML='<i class="fas facheck"></i>';setTimeout(()=>{btnElement.innerHTML='<i class="far facopy"></i>'},2000)}}catch(err){if(btnElement)btnElement.innerHTML='<i class="fas fatimes"></i>'}document.body.removeChild(textArea)}
        function escapeHtml(text){const div=document.createElement('div');div.textContent=String(text);return div.innerHTML}
        function scrollToBottom(){messagesContainer.scrollTo({top:messagesContainer.scrollHeight,behavior:'smooth'})}
        function setupEventListeners(){messageInput.addEventListener('input',()=>{sendBtn.disabled=messageInput.value.trim().length===0||AppState.isTyping;messageInput.style.height='auto';messageInput.style.height=${Math.min(messageInput.scrollHeight,140)}px});messageInput.addEventListener('keydown',(e)=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(!sendBtn.disabled)sendMessage()}});newChatBtn.addEventListener('click',newChat);copyOverlay.addEventListener('click',()=>copyOverlay.classList.remove('visible'));copyBtn.addEventListener('click',(e)=>{e.stopPropagation();copyToClipboard(e.currentTarget.dataset.text,e.currentTarget);setTimeout(()=>copyOverlay.classList.remove('visible'),500)})}
        document.addEventListener('DOMContentLoaded',()=>{new DynamicThemeManager();setupEventListeners();messageInput.focus()});
    </script>
</body>
</html>

